"""Read named tensors from a Safetensors checkpoint."""

from __future__ import annotations

import json
import math
import struct
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np


_DTYPE_WIDTHS = {
    "BF16": 2,
    "F16": 2,
    "F32": 4,
    "I32": 4,
    "I64": 8,
}

_NUMPY_DTYPES = {
    "F16": np.dtype("<f2"),
    "F32": np.dtype("<f4"),
    "I32": np.dtype("<i4"),
    "I64": np.dtype("<i8"),
}


@dataclass(frozen=True, slots=True)
class TensorInfo:
    """Where one tensor lives inside one Safetensors shard."""

    name: str
    dtype: str
    shape: tuple[int, ...]
    shard: str
    data_offsets: tuple[int, int]
    data_start: int


class SafetensorsCheckpoint:
    """A name-to-tensor view over one or more Safetensors files."""

    def __init__(self, directory: Path, tensors: dict[str, TensorInfo]) -> None:
        self.directory = directory
        self._tensors = tensors

    @classmethod
    def from_directory(cls, directory: str | Path) -> "SafetensorsCheckpoint":
        root = Path(directory)
        index_files = sorted(root.glob("*.safetensors.index.json"))
        if index_files:
            tensors = _read_index(root, index_files[0])
        else:
            shards = sorted(root.glob("*.safetensors"))
            if len(shards) != 1:
                raise ValueError("expected one Safetensors file or one index")
            tensors = _read_shard(shards[0])
        return cls(root, tensors)

    def keys(self) -> tuple[str, ...]:
        return tuple(sorted(self._tensors))

    def tensor_info(self, name: str) -> TensorInfo:
        try:
            return self._tensors[name]
        except KeyError as error:
            raise KeyError(f"unknown tensor: {name}") from error

    def load_tensor(self, name: str) -> np.ndarray:
        """Read one tensor payload instead of loading the whole checkpoint."""

        info = self.tensor_info(name)
        start, end = info.data_offsets
        with (self.directory / info.shard).open("rb") as handle:
            handle.seek(info.data_start + start)
            payload = handle.read(end - start)
        if len(payload) != end - start:
            raise ValueError(f"tensor payload is truncated: {name}")

        if info.dtype == "BF16":
            words = np.frombuffer(payload, dtype="<u2").astype(np.uint32)
            array = (words << 16).view(np.float32)
        else:
            array = np.frombuffer(payload, dtype=_NUMPY_DTYPES[info.dtype]).copy()
        return array.reshape(info.shape)


def _read_index(root: Path, path: Path) -> dict[str, TensorInfo]:
    index = json.loads(path.read_text(encoding="utf-8"))
    weight_map = index.get("weight_map")
    if not isinstance(weight_map, dict):
        raise ValueError("Safetensors index must contain weight_map")

    shard_headers = {
        shard_name: _read_shard(root / shard_name)
        for shard_name in sorted(set(weight_map.values()))
    }
    tensors: dict[str, TensorInfo] = {}
    for name, shard_name in weight_map.items():
        try:
            tensors[name] = shard_headers[shard_name][name]
        except KeyError as error:
            raise ValueError(f"index points to a missing tensor: {name}") from error
    return tensors


def _read_shard(path: Path) -> dict[str, TensorInfo]:
    with path.open("rb") as handle:
        prefix = handle.read(8)
        if len(prefix) != 8:
            raise ValueError(f"invalid Safetensors file: {path.name}")
        (header_length,) = struct.unpack("<Q", prefix)
        header = json.loads(handle.read(header_length))

    data_start = 8 + header_length
    data_size = path.stat().st_size - data_start
    tensors: dict[str, TensorInfo] = {}
    for name, metadata in header.items():
        if name != "__metadata__":
            tensors[name] = _tensor_info(
                name, metadata, path.name, data_start, data_size
            )
    return tensors


def _tensor_info(
    name: str,
    metadata: Any,
    shard: str,
    data_start: int,
    data_size: int,
) -> TensorInfo:
    dtype = metadata["dtype"]
    shape = tuple(metadata["shape"])
    start, end = metadata["data_offsets"]
    if dtype not in _DTYPE_WIDTHS:
        raise ValueError(f"unsupported Safetensors dtype: {dtype}")
    if start < 0 or end > data_size:
        raise ValueError(f"tensor offsets are outside {shard}: {name}")
    expected_bytes = math.prod(shape) * _DTYPE_WIDTHS[dtype]
    if end - start != expected_bytes:
        raise ValueError(f"tensor shape does not match its byte range: {name}")
    return TensorInfo(name, dtype, shape, shard, (start, end), data_start)

"""Encode text with the byte-level BPE stored in a Qwen3 tokenizer.json."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Iterable

import regex


class Qwen3Tokenizer:
    """A small, inference-only reader for Qwen3 byte-level BPE assets."""

    def __init__(
        self,
        vocabulary: dict[str, int],
        merges: list[str | list[str]],
        pretoken_pattern: str,
        special_tokens: dict[str, int],
    ) -> None:
        self.vocabulary = vocabulary
        self.tokens = {token_id: token for token, token_id in vocabulary.items()}
        self.special_tokens = special_tokens
        self.special_token_ids = frozenset(special_tokens.values())
        self._merge_ranks = {
            self._parse_merge(pair): rank for rank, pair in enumerate(merges)
        }
        self._pretokenizer = regex.compile(pretoken_pattern)
        self._special_pattern = (
            regex.compile(
                "|".join(
                    regex.escape(token)
                    for token in sorted(special_tokens, key=len, reverse=True)
                )
            )
            if special_tokens
            else None
        )
        self._byte_encoder, self._byte_decoder = _byte_alphabet()
        self._bpe_cache: dict[str, tuple[str, ...]] = {}

    @classmethod
    def from_file(cls, path: str | Path) -> "Qwen3Tokenizer":
        """Read the vocabulary, merge ranks, and special tokens."""

        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        model = raw.get("model")
        if not isinstance(model, dict) or model.get("type") != "BPE":
            raise ValueError("tokenizer.json must contain a BPE model")
        vocabulary = model.get("vocab")
        merges = model.get("merges")
        if not isinstance(vocabulary, dict) or not isinstance(merges, list):
            raise ValueError("tokenizer.json is missing its vocabulary or merges")
        if not all(
            isinstance(token, str) and isinstance(token_id, int)
            for token, token_id in vocabulary.items()
        ):
            raise ValueError("tokenizer vocabulary must map strings to integer IDs")

        special_tokens = {
            item["content"]: item["id"]
            for item in raw.get("added_tokens", [])
            if item.get("special") is True
        }
        full_vocabulary = {**vocabulary, **special_tokens}
        if len(set(full_vocabulary.values())) != len(full_vocabulary):
            raise ValueError("tokenizer IDs must be unique")
        return cls(
            full_vocabulary,
            merges,
            _find_split_pattern(raw.get("pre_tokenizer")),
            special_tokens,
        )

    @staticmethod
    def _parse_merge(pair: str | list[str]) -> tuple[str, str]:
        parts = pair.split(" ", 1) if isinstance(pair, str) else pair
        if len(parts) != 2:
            raise ValueError(f"invalid BPE merge: {pair!r}")
        return parts[0], parts[1]

    @property
    def vocab_size(self) -> int:
        return len(self.vocabulary)

    def token_to_id(self, token: str) -> int:
        try:
            return self.vocabulary[token]
        except KeyError as error:
            raise KeyError(f"unknown token: {token!r}") from error

    def id_to_token(self, token_id: int) -> str:
        try:
            return self.tokens[token_id]
        except KeyError as error:
            raise KeyError(f"unknown token ID: {token_id}") from error

    def encode(self, text: str) -> list[int]:
        """Turn text into the exact token IDs used to index model embeddings."""

        if self._special_pattern is None:
            return self._encode_text(text)

        token_ids: list[int] = []
        start = 0
        for match in self._special_pattern.finditer(text):
            token_ids.extend(self._encode_text(text[start : match.start()]))
            token_ids.append(self.special_tokens[match.group(0)])
            start = match.end()
        token_ids.extend(self._encode_text(text[start:]))
        return token_ids

    def _encode_text(self, text: str) -> list[int]:
        token_ids: list[int] = []
        for match in self._pretokenizer.finditer(text):
            byte_token = "".join(
                self._byte_encoder[byte] for byte in match.group(0).encode("utf-8")
            )
            pieces = self._bpe_cache.get(byte_token)
            if pieces is None:
                pieces = _merge_token(byte_token, self._merge_ranks)
                self._bpe_cache[byte_token] = pieces
            try:
                token_ids.extend(self.vocabulary[piece] for piece in pieces)
            except KeyError as error:
                raise ValueError(f"BPE produced an unknown token: {error.args[0]!r}") from error
        return token_ids

    def decode(
        self,
        token_ids: Iterable[int],
        *,
        skip_special_tokens: bool = False,
        errors: str = "replace",
    ) -> str:
        """Reassemble token IDs into UTF-8 text."""

        output: list[str] = []
        byte_buffer = bytearray()

        def flush_bytes() -> None:
            if byte_buffer:
                output.append(byte_buffer.decode("utf-8", errors=errors))
                byte_buffer.clear()

        for token_id in token_ids:
            token = self.id_to_token(token_id)
            if token_id in self.special_token_ids:
                flush_bytes()
                if not skip_special_tokens:
                    output.append(token)
                continue
            try:
                byte_buffer.extend(self._byte_decoder[character] for character in token)
            except KeyError as error:
                raise ValueError(
                    f"token contains a character outside the byte alphabet: {token!r}"
                ) from error
        flush_bytes()
        return "".join(output)


def _byte_alphabet() -> tuple[dict[int, str], dict[str, int]]:
    """Map all 256 byte values to visible Unicode characters and back."""

    byte_values = list(range(ord("!"), ord("~") + 1))
    byte_values += list(range(ord("¡"), ord("¬") + 1))
    byte_values += list(range(ord("®"), ord("ÿ") + 1))
    code_points = byte_values.copy()
    extra = 0
    for byte in range(256):
        if byte not in byte_values:
            byte_values.append(byte)
            code_points.append(256 + extra)
            extra += 1
    encoder = dict(zip(byte_values, map(chr, code_points), strict=True))
    return encoder, {character: byte for byte, character in encoder.items()}


def _merge_token(
    token: str, merge_ranks: dict[tuple[str, str], int]
) -> tuple[str, ...]:
    """Repeatedly apply the highest-priority merge still present in one token."""

    pieces = tuple(token)
    while len(pieces) > 1:
        adjacent_pairs = zip(pieces, pieces[1:])
        best_pair = min(adjacent_pairs, key=lambda pair: merge_ranks.get(pair, float("inf")))
        if best_pair not in merge_ranks:
            break

        merged: list[str] = []
        index = 0
        while index < len(pieces):
            if index + 1 < len(pieces) and pieces[index : index + 2] == best_pair:
                merged.append("".join(best_pair))
                index += 2
            else:
                merged.append(pieces[index])
                index += 1
        pieces = tuple(merged)
    return pieces


def _find_split_pattern(pretokenizer: object) -> str:
    if not isinstance(pretokenizer, dict):
        raise ValueError("tokenizer.json is missing its pre-tokenizer")
    if pretokenizer.get("type") == "Split":
        pattern = pretokenizer.get("pattern")
        if isinstance(pattern, dict) and isinstance(pattern.get("Regex"), str):
            return pattern["Regex"]
    for child in pretokenizer.get("pretokenizers", []):
        try:
            return _find_split_pattern(child)
        except ValueError:
            pass
    raise ValueError("tokenizer.json does not contain a regex Split pre-tokenizer")

"""Small NumPy layers shared by Qwen3 MoE inference modules."""

from __future__ import annotations

import numpy as np


class Embedding:
    """Look up one hidden vector for every token ID."""

    def __init__(self, weight: np.ndarray) -> None:
        if weight.ndim != 2:
            raise ValueError("embedding weight must have shape [V,D]")
        self.weight = weight

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if not np.issubdtype(token_ids.dtype, np.integer):
            raise ValueError("token IDs must be integers")
        if np.any(token_ids < 0) or np.any(token_ids >= self.weight.shape[0]):
            raise ValueError("token ID is outside the embedding vocabulary")
        return self.weight[token_ids]


class RMSNorm:
    """Scale hidden states by their root-mean-square magnitude."""

    def __init__(self, weight: np.ndarray, epsilon: float) -> None:
        if weight.ndim != 1:
            raise ValueError("RMSNorm weight must have shape [D]")
        if epsilon <= 0:
            raise ValueError("RMSNorm epsilon must be positive")
        self.weight = weight
        self.epsilon = epsilon

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[0]:
            raise ValueError("hidden size does not match RMSNorm weight")
        values = hidden_states.astype(np.float32, copy=False)
        mean_square = np.mean(np.square(values), axis=-1, keepdims=True)
        return values * np.reciprocal(np.sqrt(mean_square + self.epsilon)) * self.weight


class Linear:
    """Apply a learned projection to the last tensor dimension."""

    def __init__(self, weight: np.ndarray, bias: np.ndarray | None = None) -> None:
        if weight.ndim != 2:
            raise ValueError("linear weight must have shape [O,I]")
        if bias is not None and bias.shape != (weight.shape[0],):
            raise ValueError("linear bias must have shape [O]")
        self.weight = weight
        self.bias = bias

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[1]:
            raise ValueError("input size does not match linear weight")
        output = hidden_states @ self.weight.T
        return output if self.bias is None else output + self.bias

"""Rotary position embeddings for Qwen3 attention."""

from __future__ import annotations

import numpy as np


class RotaryEmbedding:
    """Build the cosine and sine values used to rotate attention heads."""

    def __init__(self, head_dim: int, theta: float = 1_000_000.0) -> None:
        if isinstance(head_dim, bool) or not isinstance(head_dim, int) or head_dim <= 0:
            raise ValueError("RoPE head dimension must be a positive integer")
        if head_dim % 2:
            raise ValueError("RoPE head dimension must be even")
        if theta <= 0:
            raise ValueError("RoPE theta must be positive")
        dimensions = np.arange(0, head_dim, 2, dtype=np.float32)
        self.inverse_frequencies = 1.0 / (theta ** (dimensions / head_dim))

    def __call__(self, position_ids: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        position_ids = np.asarray(position_ids)
        if position_ids.ndim != 2:
            raise ValueError("position IDs must have shape [B,S]")
        if not np.issubdtype(position_ids.dtype, np.integer):
            raise ValueError("position IDs must be integers")
        if np.any(position_ids < 0):
            raise ValueError("position IDs must be non-negative")
        angles = position_ids.astype(np.float32)[..., None] * self.inverse_frequencies
        angles = np.concatenate((angles, angles), axis=-1)
        return np.cos(angles), np.sin(angles)


def _rotate_half(hidden_states: np.ndarray) -> np.ndarray:
    first_half, second_half = np.split(hidden_states, 2, axis=-1)
    return np.concatenate((-second_half, first_half), axis=-1)


def apply_rotary_position_embedding(
    query: np.ndarray,
    key: np.ndarray,
    cosine: np.ndarray,
    sine: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    """Rotate Query and Key while allowing different Q and KV head counts."""

    query = np.asarray(query)
    key = np.asarray(key)
    cosine = np.asarray(cosine)
    sine = np.asarray(sine)
    if query.ndim != 4 or key.ndim != 4:
        raise ValueError("Query and Key must have shape [B,H,S,Hd]")
    if query.shape[0] != key.shape[0] or query.shape[2:] != key.shape[2:]:
        raise ValueError("Query and Key must share batch, sequence, and head dimensions")
    expected = (query.shape[0], query.shape[2], query.shape[3])
    if cosine.shape != expected or sine.shape != expected:
        raise ValueError("RoPE cosine and sine must have shape [B,S,Hd]")
    cosine = cosine[:, None, :, :]
    sine = sine[:, None, :, :]
    rotated_query = query * cosine + _rotate_half(query) * sine
    rotated_key = key * cosine + _rotate_half(key) * sine
    return rotated_query, rotated_key

"""Decoder layers and causal language model assembly for Qwen3 MoE."""

from __future__ import annotations

import numpy as np

from qwen3_moe.attention import Qwen3Attention
from qwen3_moe.cache import KVCache
from qwen3_moe.checkpoint import SafetensorsCheckpoint
from qwen3_moe.config import Qwen3MoeConfig
from qwen3_moe.layers import Embedding, Linear
from qwen3_moe.layers import RMSNorm
from qwen3_moe.moe import Qwen3SparseMoeBlock


class Qwen3DecoderLayer:
    """Combine pre-norm Attention and sparse MoE with residual connections."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        input_layernorm_weight: np.ndarray,
        q_proj_weight: np.ndarray,
        k_proj_weight: np.ndarray,
        v_proj_weight: np.ndarray,
        o_proj_weight: np.ndarray,
        q_norm_weight: np.ndarray,
        k_norm_weight: np.ndarray,
        post_attention_layernorm_weight: np.ndarray,
        router_weight: np.ndarray,
        gate_up_proj_weight: np.ndarray,
        down_proj_weight: np.ndarray,
    ) -> None:
        self.hidden_size = config.hidden_size
        self.input_layernorm = RMSNorm(
            input_layernorm_weight, config.rms_norm_eps
        )
        self.self_attention = Qwen3Attention(
            config,
            q_proj_weight,
            k_proj_weight,
            v_proj_weight,
            o_proj_weight,
            q_norm_weight,
            k_norm_weight,
        )
        self.post_attention_layernorm = RMSNorm(
            post_attention_layernorm_weight, config.rms_norm_eps
        )
        self.mlp = Qwen3SparseMoeBlock(
            config,
            router_weight,
            gate_up_proj_weight,
            down_proj_weight,
        )

    def _attention_block(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention(hidden_states, position_ids)
        return residual + hidden_states

    def _moe_block(self, hidden_states: np.ndarray) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        return residual + hidden_states

    def __call__(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._attention_block(hidden_states, position_ids)
        return self._moe_block(hidden_states)

    def _cached_attention_block(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention.cached(
            hidden_states, position_ids, cache, layer_index
        )
        return residual + hidden_states

    def cached(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        """Run one decoder layer while updating its Key/Value cache."""
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._cached_attention_block(
            hidden_states, position_ids, cache, layer_index
        )
        return self._moe_block(hidden_states)


class Qwen3MoeForCausalLM:
    """Run full-prompt Qwen3 MoE inference and return vocabulary logits."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        embed_tokens_weight: np.ndarray,
        layers: list[Qwen3DecoderLayer],
        norm_weight: np.ndarray,
        lm_head_weight: np.ndarray,
    ) -> None:
        if embed_tokens_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("embedding weight does not match config")
        if len(layers) != config.num_hidden_layers:
            raise ValueError("decoder layer count does not match config")
        if norm_weight.shape != (config.hidden_size,):
            raise ValueError("final norm weight does not match config")
        if lm_head_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("LM Head weight does not match config")

        self.embed_tokens = Embedding(embed_tokens_weight)
        self.layers = layers
        self.norm = RMSNorm(norm_weight, config.rms_norm_eps)
        self.lm_head = Linear(lm_head_weight)

    @classmethod
    def from_checkpoint(
        cls,
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
    ) -> "Qwen3MoeForCausalLM":
        embed_tokens_weight = checkpoint.load_tensor("model.embed_tokens.weight")
        layers = [
            cls._load_decoder_layer(config, checkpoint, layer_index)
            for layer_index in range(config.num_hidden_layers)
        ]
        norm_weight = checkpoint.load_tensor("model.norm.weight")
        lm_head_weight = (
            embed_tokens_weight
            if config.tie_word_embeddings
            else checkpoint.load_tensor("lm_head.weight")
        )
        return cls(
            config,
            embed_tokens_weight,
            layers,
            norm_weight,
            lm_head_weight,
        )

    @staticmethod
    def _load_decoder_layer(
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
        layer_index: int,
    ) -> Qwen3DecoderLayer:
        prefix = f"model.layers.{layer_index}"
        load = checkpoint.load_tensor
        return Qwen3DecoderLayer(
            config,
            load(f"{prefix}.input_layernorm.weight"),
            load(f"{prefix}.self_attn.q_proj.weight"),
            load(f"{prefix}.self_attn.k_proj.weight"),
            load(f"{prefix}.self_attn.v_proj.weight"),
            load(f"{prefix}.self_attn.o_proj.weight"),
            load(f"{prefix}.self_attn.q_norm.weight"),
            load(f"{prefix}.self_attn.k_norm.weight"),
            load(f"{prefix}.post_attention_layernorm.weight"),
            load(f"{prefix}.mlp.gate.weight"),
            load(f"{prefix}.mlp.experts.gate_up_proj"),
            load(f"{prefix}.mlp.experts.down_proj"),
        )

    @staticmethod
    def _position_ids(token_ids: np.ndarray) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        positions = np.arange(sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._position_ids(token_ids)
        hidden_states = self.embed_tokens(token_ids)
        for layer in self.layers:
            hidden_states = layer(hidden_states, position_ids)
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

    @staticmethod
    def _cached_position_ids(
        token_ids: np.ndarray, cache: KVCache
    ) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        start = cache.sequence_length
        positions = np.arange(start, start + sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def cached(self, token_ids: np.ndarray, cache: KVCache) -> np.ndarray:
        """Run prefill or decode while appending every layer's Key/Value state."""
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._cached_position_ids(token_ids, cache)
        hidden_states = self.embed_tokens(token_ids)
        for layer_index, layer in enumerate(self.layers):
            hidden_states = layer.cached(
                hidden_states, position_ids, cache, layer_index
            )
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

"""Next-token selection from Causal LM logits."""

from __future__ import annotations

import numpy as np


def last_token_logits(logits: np.ndarray) -> np.ndarray:
    """Return the vocabulary logits after the final input token."""
    logits = np.asarray(logits)
    if logits.ndim != 3:
        raise ValueError("logits must have shape [B,S,V]")
    if logits.shape[1] == 0:
        raise ValueError("logits must contain at least one sequence position")
    if logits.shape[2] == 0:
        raise ValueError("logits must contain at least one vocabulary entry")
    return logits[:, -1, :]


def greedy_next_token(logits: np.ndarray) -> np.ndarray:
    """Choose the highest-logit token for each batch item."""
    return np.argmax(last_token_logits(logits), axis=-1)


def next_token_probabilities(
    logits: np.ndarray,
    temperature: float = 1.0,
) -> np.ndarray:
    """Convert final-position logits to probabilities with temperature."""
    if not np.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be a finite positive number")

    scaled_logits = last_token_logits(logits) / temperature
    shifted_logits = scaled_logits - np.max(scaled_logits, axis=-1, keepdims=True)
    unnormalized = np.exp(shifted_logits)
    return unnormalized / np.sum(unnormalized, axis=-1, keepdims=True)


def sample_next_token(
    logits: np.ndarray,
    temperature: float = 1.0,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Sample one token ID per batch item from final-position logits."""
    probabilities = next_token_probabilities(logits, temperature)
    rng = np.random.default_rng() if rng is None else rng
    vocabulary_size = probabilities.shape[-1]
    return np.asarray(
        [
            rng.choice(vocabulary_size, p=batch_probabilities)
            for batch_probabilities in probabilities
        ],
        dtype=np.int64,
    )


def generate_token_ids(
    model: object,
    prompt_token_ids: np.ndarray,
    max_new_tokens: int,
    *,
    eos_token_id: int | None = None,
    temperature: float | None = None,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Generate one continuation with cached prefill and decode."""
    prompt_token_ids = np.asarray(prompt_token_ids)
    if prompt_token_ids.ndim != 2 or prompt_token_ids.shape[0] != 1:
        raise ValueError("generation expects one prompt with shape [1,S]")
    if prompt_token_ids.shape[1] == 0:
        raise ValueError("generation requires at least one prompt token")
    if not np.issubdtype(prompt_token_ids.dtype, np.integer):
        raise ValueError("prompt token IDs must be integers")
    if isinstance(max_new_tokens, bool) or not isinstance(max_new_tokens, int):
        raise TypeError("max_new_tokens must be an integer")
    if max_new_tokens < 0:
        raise ValueError("max_new_tokens cannot be negative")

    generated = prompt_token_ids.astype(np.int64, copy=True)
    if max_new_tokens == 0:
        return generated

    layers = getattr(model, "layers", None)
    if not isinstance(layers, list) or not layers:
        raise ValueError("model must expose a non-empty decoder layer list")
    cache = KVCache(len(layers))
    logits = model.cached(generated, cache)

    for step in range(max_new_tokens):
        next_token = (
            greedy_next_token(logits)
            if temperature is None
            else sample_next_token(logits, temperature, rng)
        )
        generated = np.concatenate((generated, next_token[:, None]), axis=1)
        if eos_token_id is not None and next_token[0] == eos_token_id:
            break
        if step + 1 == max_new_tokens:
            break
        logits = model.cached(next_token[:, None], cache)
    return generated

"""Per-layer Key/Value storage for cached Qwen3 MoE decoding."""

from __future__ import annotations

import numpy as np


class KVCache:
    """Store and append grouped-query Key/Value tensors for every layer."""

    def __init__(self, num_hidden_layers: int) -> None:
        if isinstance(num_hidden_layers, bool) or not isinstance(
            num_hidden_layers, int
        ) or num_hidden_layers <= 0:
            raise ValueError("num_hidden_layers must be a positive integer")
        self._keys: list[np.ndarray | None] = [None] * num_hidden_layers
        self._values: list[np.ndarray | None] = [None] * num_hidden_layers

    def _validate_layer_index(self, layer_index: int) -> None:
        if isinstance(layer_index, bool) or not isinstance(layer_index, int):
            raise TypeError("layer_index must be an integer")
        if not 0 <= layer_index < len(self._keys):
            raise IndexError("layer_index is outside the KV Cache")

    @staticmethod
    def _validate_key_value(key: np.ndarray, value: np.ndarray) -> None:
        if key.ndim != 4 or value.ndim != 4:
            raise ValueError("cached Key and Value must have shape [B,Hkv,S,Dh]")
        if key.shape != value.shape:
            raise ValueError("cached Key and Value shapes must match")
        if key.shape[2] == 0:
            raise ValueError("cached Key and Value must contain at least one token")

    def get(self, layer_index: int) -> tuple[np.ndarray, np.ndarray] | None:
        """Return one layer's cached tensors, or None before its first update."""
        self._validate_layer_index(layer_index)
        key = self._keys[layer_index]
        value = self._values[layer_index]
        if key is None or value is None:
            return None
        return key, value

    def update(
        self,
        layer_index: int,
        key: np.ndarray,
        value: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Append new Key/Value states and return the complete layer cache."""
        self._validate_layer_index(layer_index)
        key = np.asarray(key)
        value = np.asarray(value)
        self._validate_key_value(key, value)

        cached = self.get(layer_index)
        if cached is not None:
            cached_key, cached_value = cached
            if key.shape[:2] + key.shape[3:] != cached_key.shape[:2] + cached_key.shape[3:]:
                raise ValueError("new Key/Value dimensions do not match the layer cache")
            key = np.concatenate((cached_key, key), axis=2)
            value = np.concatenate((cached_value, value), axis=2)

        self._keys[layer_index] = key
        self._values[layer_index] = value
        return key, value

    @property
    def sequence_length(self) -> int:
        """Return the shared cached length after all populated layers agree."""
        lengths = {key.shape[2] for key in self._keys if key is not None}
        if not lengths:
            return 0
        if len(lengths) != 1:
            raise ValueError("KV Cache layers do not have the same sequence length")
        return lengths.pop()

"""Read named tensors from a Safetensors checkpoint."""

from __future__ import annotations

import json
import math
import struct
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np


_DTYPE_WIDTHS = {
    "BF16": 2,
    "F16": 2,
    "F32": 4,
    "I32": 4,
    "I64": 8,
}

_NUMPY_DTYPES = {
    "F16": np.dtype("<f2"),
    "F32": np.dtype("<f4"),
    "I32": np.dtype("<i4"),
    "I64": np.dtype("<i8"),
}


@dataclass(frozen=True, slots=True)
class TensorInfo:
    """Where one tensor lives inside one Safetensors shard."""

    name: str
    dtype: str
    shape: tuple[int, ...]
    shard: str
    data_offsets: tuple[int, int]
    data_start: int


class SafetensorsCheckpoint:
    """A name-to-tensor view over one or more Safetensors files."""

    def __init__(self, directory: Path, tensors: dict[str, TensorInfo]) -> None:
        self.directory = directory
        self._tensors = tensors

    @classmethod
    def from_directory(cls, directory: str | Path) -> "SafetensorsCheckpoint":
        root = Path(directory)
        index_files = sorted(root.glob("*.safetensors.index.json"))
        if index_files:
            tensors = _read_index(root, index_files[0])
        else:
            shards = sorted(root.glob("*.safetensors"))
            if len(shards) != 1:
                raise ValueError("expected one Safetensors file or one index")
            tensors = _read_shard(shards[0])
        return cls(root, tensors)

    def keys(self) -> tuple[str, ...]:
        return tuple(sorted(self._tensors))

    def tensor_info(self, name: str) -> TensorInfo:
        try:
            return self._tensors[name]
        except KeyError as error:
            raise KeyError(f"unknown tensor: {name}") from error

    def load_tensor(self, name: str) -> np.ndarray:
        """Read one tensor payload instead of loading the whole checkpoint."""

        info = self.tensor_info(name)
        start, end = info.data_offsets
        with (self.directory / info.shard).open("rb") as handle:
            handle.seek(info.data_start + start)
            payload = handle.read(end - start)
        if len(payload) != end - start:
            raise ValueError(f"tensor payload is truncated: {name}")

        if info.dtype == "BF16":
            words = np.frombuffer(payload, dtype="<u2").astype(np.uint32)
            array = (words << 16).view(np.float32)
        else:
            array = np.frombuffer(payload, dtype=_NUMPY_DTYPES[info.dtype]).copy()
        return array.reshape(info.shape)


def _read_index(root: Path, path: Path) -> dict[str, TensorInfo]:
    index = json.loads(path.read_text(encoding="utf-8"))
    weight_map = index.get("weight_map")
    if not isinstance(weight_map, dict):
        raise ValueError("Safetensors index must contain weight_map")

    shard_headers = {
        shard_name: _read_shard(root / shard_name)
        for shard_name in sorted(set(weight_map.values()))
    }
    tensors: dict[str, TensorInfo] = {}
    for name, shard_name in weight_map.items():
        try:
            tensors[name] = shard_headers[shard_name][name]
        except KeyError as error:
            raise ValueError(f"index points to a missing tensor: {name}") from error
    return tensors


def _read_shard(path: Path) -> dict[str, TensorInfo]:
    with path.open("rb") as handle:
        prefix = handle.read(8)
        if len(prefix) != 8:
            raise ValueError(f"invalid Safetensors file: {path.name}")
        (header_length,) = struct.unpack("<Q", prefix)
        header = json.loads(handle.read(header_length))

    data_start = 8 + header_length
    data_size = path.stat().st_size - data_start
    tensors: dict[str, TensorInfo] = {}
    for name, metadata in header.items():
        if name != "__metadata__":
            tensors[name] = _tensor_info(
                name, metadata, path.name, data_start, data_size
            )
    return tensors


def _tensor_info(
    name: str,
    metadata: Any,
    shard: str,
    data_start: int,
    data_size: int,
) -> TensorInfo:
    dtype = metadata["dtype"]
    shape = tuple(metadata["shape"])
    start, end = metadata["data_offsets"]
    if dtype not in _DTYPE_WIDTHS:
        raise ValueError(f"unsupported Safetensors dtype: {dtype}")
    if start < 0 or end > data_size:
        raise ValueError(f"tensor offsets are outside {shard}: {name}")
    expected_bytes = math.prod(shape) * _DTYPE_WIDTHS[dtype]
    if end - start != expected_bytes:
        raise ValueError(f"tensor shape does not match its byte range: {name}")
    return TensorInfo(name, dtype, shape, shard, (start, end), data_start)

"""Encode text with the byte-level BPE stored in a Qwen3 tokenizer.json."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Iterable

import regex


class Qwen3Tokenizer:
    """A small, inference-only reader for Qwen3 byte-level BPE assets."""

    def __init__(
        self,
        vocabulary: dict[str, int],
        merges: list[str | list[str]],
        pretoken_pattern: str,
        special_tokens: dict[str, int],
    ) -> None:
        self.vocabulary = vocabulary
        self.tokens = {token_id: token for token, token_id in vocabulary.items()}
        self.special_tokens = special_tokens
        self.special_token_ids = frozenset(special_tokens.values())
        self._merge_ranks = {
            self._parse_merge(pair): rank for rank, pair in enumerate(merges)
        }
        self._pretokenizer = regex.compile(pretoken_pattern)
        self._special_pattern = (
            regex.compile(
                "|".join(
                    regex.escape(token)
                    for token in sorted(special_tokens, key=len, reverse=True)
                )
            )
            if special_tokens
            else None
        )
        self._byte_encoder, self._byte_decoder = _byte_alphabet()
        self._bpe_cache: dict[str, tuple[str, ...]] = {}

    @classmethod
    def from_file(cls, path: str | Path) -> "Qwen3Tokenizer":
        """Read the vocabulary, merge ranks, and special tokens."""

        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        model = raw.get("model")
        if not isinstance(model, dict) or model.get("type") != "BPE":
            raise ValueError("tokenizer.json must contain a BPE model")
        vocabulary = model.get("vocab")
        merges = model.get("merges")
        if not isinstance(vocabulary, dict) or not isinstance(merges, list):
            raise ValueError("tokenizer.json is missing its vocabulary or merges")
        if not all(
            isinstance(token, str) and isinstance(token_id, int)
            for token, token_id in vocabulary.items()
        ):
            raise ValueError("tokenizer vocabulary must map strings to integer IDs")

        special_tokens = {
            item["content"]: item["id"]
            for item in raw.get("added_tokens", [])
            if item.get("special") is True
        }
        full_vocabulary = {**vocabulary, **special_tokens}
        if len(set(full_vocabulary.values())) != len(full_vocabulary):
            raise ValueError("tokenizer IDs must be unique")
        return cls(
            full_vocabulary,
            merges,
            _find_split_pattern(raw.get("pre_tokenizer")),
            special_tokens,
        )

    @staticmethod
    def _parse_merge(pair: str | list[str]) -> tuple[str, str]:
        parts = pair.split(" ", 1) if isinstance(pair, str) else pair
        if len(parts) != 2:
            raise ValueError(f"invalid BPE merge: {pair!r}")
        return parts[0], parts[1]

    @property
    def vocab_size(self) -> int:
        return len(self.vocabulary)

    def token_to_id(self, token: str) -> int:
        try:
            return self.vocabulary[token]
        except KeyError as error:
            raise KeyError(f"unknown token: {token!r}") from error

    def id_to_token(self, token_id: int) -> str:
        try:
            return self.tokens[token_id]
        except KeyError as error:
            raise KeyError(f"unknown token ID: {token_id}") from error

    def encode(self, text: str) -> list[int]:
        """Turn text into the exact token IDs used to index model embeddings."""

        if self._special_pattern is None:
            return self._encode_text(text)

        token_ids: list[int] = []
        start = 0
        for match in self._special_pattern.finditer(text):
            token_ids.extend(self._encode_text(text[start : match.start()]))
            token_ids.append(self.special_tokens[match.group(0)])
            start = match.end()
        token_ids.extend(self._encode_text(text[start:]))
        return token_ids

    def _encode_text(self, text: str) -> list[int]:
        token_ids: list[int] = []
        for match in self._pretokenizer.finditer(text):
            byte_token = "".join(
                self._byte_encoder[byte] for byte in match.group(0).encode("utf-8")
            )
            pieces = self._bpe_cache.get(byte_token)
            if pieces is None:
                pieces = _merge_token(byte_token, self._merge_ranks)
                self._bpe_cache[byte_token] = pieces
            try:
                token_ids.extend(self.vocabulary[piece] for piece in pieces)
            except KeyError as error:
                raise ValueError(f"BPE produced an unknown token: {error.args[0]!r}") from error
        return token_ids

    def decode(
        self,
        token_ids: Iterable[int],
        *,
        skip_special_tokens: bool = False,
        errors: str = "replace",
    ) -> str:
        """Reassemble token IDs into UTF-8 text."""

        output: list[str] = []
        byte_buffer = bytearray()

        def flush_bytes() -> None:
            if byte_buffer:
                output.append(byte_buffer.decode("utf-8", errors=errors))
                byte_buffer.clear()

        for token_id in token_ids:
            token = self.id_to_token(token_id)
            if token_id in self.special_token_ids:
                flush_bytes()
                if not skip_special_tokens:
                    output.append(token)
                continue
            try:
                byte_buffer.extend(self._byte_decoder[character] for character in token)
            except KeyError as error:
                raise ValueError(
                    f"token contains a character outside the byte alphabet: {token!r}"
                ) from error
        flush_bytes()
        return "".join(output)


def _byte_alphabet() -> tuple[dict[int, str], dict[str, int]]:
    """Map all 256 byte values to visible Unicode characters and back."""

    byte_values = list(range(ord("!"), ord("~") + 1))
    byte_values += list(range(ord("¡"), ord("¬") + 1))
    byte_values += list(range(ord("®"), ord("ÿ") + 1))
    code_points = byte_values.copy()
    extra = 0
    for byte in range(256):
        if byte not in byte_values:
            byte_values.append(byte)
            code_points.append(256 + extra)
            extra += 1
    encoder = dict(zip(byte_values, map(chr, code_points), strict=True))
    return encoder, {character: byte for byte, character in encoder.items()}


def _merge_token(
    token: str, merge_ranks: dict[tuple[str, str], int]
) -> tuple[str, ...]:
    """Repeatedly apply the highest-priority merge still present in one token."""

    pieces = tuple(token)
    while len(pieces) > 1:
        adjacent_pairs = zip(pieces, pieces[1:])
        best_pair = min(adjacent_pairs, key=lambda pair: merge_ranks.get(pair, float("inf")))
        if best_pair not in merge_ranks:
            break

        merged: list[str] = []
        index = 0
        while index < len(pieces):
            if index + 1 < len(pieces) and pieces[index : index + 2] == best_pair:
                merged.append("".join(best_pair))
                index += 2
            else:
                merged.append(pieces[index])
                index += 1
        pieces = tuple(merged)
    return pieces


def _find_split_pattern(pretokenizer: object) -> str:
    if not isinstance(pretokenizer, dict):
        raise ValueError("tokenizer.json is missing its pre-tokenizer")
    if pretokenizer.get("type") == "Split":
        pattern = pretokenizer.get("pattern")
        if isinstance(pattern, dict) and isinstance(pattern.get("Regex"), str):
            return pattern["Regex"]
    for child in pretokenizer.get("pretokenizers", []):
        try:
            return _find_split_pattern(child)
        except ValueError:
            pass
    raise ValueError("tokenizer.json does not contain a regex Split pre-tokenizer")

"""Small NumPy layers shared by Qwen3 MoE inference modules."""

from __future__ import annotations

import numpy as np


class Embedding:
    """Look up one hidden vector for every token ID."""

    def __init__(self, weight: np.ndarray) -> None:
        if weight.ndim != 2:
            raise ValueError("embedding weight must have shape [V,D]")
        self.weight = weight

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if not np.issubdtype(token_ids.dtype, np.integer):
            raise ValueError("token IDs must be integers")
        if np.any(token_ids < 0) or np.any(token_ids >= self.weight.shape[0]):
            raise ValueError("token ID is outside the embedding vocabulary")
        return self.weight[token_ids]


class RMSNorm:
    """Scale hidden states by their root-mean-square magnitude."""

    def __init__(self, weight: np.ndarray, epsilon: float) -> None:
        if weight.ndim != 1:
            raise ValueError("RMSNorm weight must have shape [D]")
        if epsilon <= 0:
            raise ValueError("RMSNorm epsilon must be positive")
        self.weight = weight
        self.epsilon = epsilon

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[0]:
            raise ValueError("hidden size does not match RMSNorm weight")
        values = hidden_states.astype(np.float32, copy=False)
        mean_square = np.mean(np.square(values), axis=-1, keepdims=True)
        return values * np.reciprocal(np.sqrt(mean_square + self.epsilon)) * self.weight


class Linear:
    """Apply a learned projection to the last tensor dimension."""

    def __init__(self, weight: np.ndarray, bias: np.ndarray | None = None) -> None:
        if weight.ndim != 2:
            raise ValueError("linear weight must have shape [O,I]")
        if bias is not None and bias.shape != (weight.shape[0],):
            raise ValueError("linear bias must have shape [O]")
        self.weight = weight
        self.bias = bias

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[1]:
            raise ValueError("input size does not match linear weight")
        output = hidden_states @ self.weight.T
        return output if self.bias is None else output + self.bias

"""Rotary position embeddings for Qwen3 attention."""

from __future__ import annotations

import numpy as np


class RotaryEmbedding:
    """Build the cosine and sine values used to rotate attention heads."""

    def __init__(self, head_dim: int, theta: float = 1_000_000.0) -> None:
        if isinstance(head_dim, bool) or not isinstance(head_dim, int) or head_dim <= 0:
            raise ValueError("RoPE head dimension must be a positive integer")
        if head_dim % 2:
            raise ValueError("RoPE head dimension must be even")
        if theta <= 0:
            raise ValueError("RoPE theta must be positive")
        dimensions = np.arange(0, head_dim, 2, dtype=np.float32)
        self.inverse_frequencies = 1.0 / (theta ** (dimensions / head_dim))

    def __call__(self, position_ids: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        position_ids = np.asarray(position_ids)
        if position_ids.ndim != 2:
            raise ValueError("position IDs must have shape [B,S]")
        if not np.issubdtype(position_ids.dtype, np.integer):
            raise ValueError("position IDs must be integers")
        if np.any(position_ids < 0):
            raise ValueError("position IDs must be non-negative")
        angles = position_ids.astype(np.float32)[..., None] * self.inverse_frequencies
        angles = np.concatenate((angles, angles), axis=-1)
        return np.cos(angles), np.sin(angles)


def _rotate_half(hidden_states: np.ndarray) -> np.ndarray:
    first_half, second_half = np.split(hidden_states, 2, axis=-1)
    return np.concatenate((-second_half, first_half), axis=-1)


def apply_rotary_position_embedding(
    query: np.ndarray,
    key: np.ndarray,
    cosine: np.ndarray,
    sine: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    """Rotate Query and Key while allowing different Q and KV head counts."""

    query = np.asarray(query)
    key = np.asarray(key)
    cosine = np.asarray(cosine)
    sine = np.asarray(sine)
    if query.ndim != 4 or key.ndim != 4:
        raise ValueError("Query and Key must have shape [B,H,S,Hd]")
    if query.shape[0] != key.shape[0] or query.shape[2:] != key.shape[2:]:
        raise ValueError("Query and Key must share batch, sequence, and head dimensions")
    expected = (query.shape[0], query.shape[2], query.shape[3])
    if cosine.shape != expected or sine.shape != expected:
        raise ValueError("RoPE cosine and sine must have shape [B,S,Hd]")
    cosine = cosine[:, None, :, :]
    sine = sine[:, None, :, :]
    rotated_query = query * cosine + _rotate_half(query) * sine
    rotated_key = key * cosine + _rotate_half(key) * sine
    return rotated_query, rotated_key

"""Decoder layers and causal language model assembly for Qwen3 MoE."""

from __future__ import annotations

import numpy as np

from qwen3_moe.attention import Qwen3Attention
from qwen3_moe.cache import KVCache
from qwen3_moe.checkpoint import SafetensorsCheckpoint
from qwen3_moe.config import Qwen3MoeConfig
from qwen3_moe.layers import Embedding, Linear
from qwen3_moe.layers import RMSNorm
from qwen3_moe.moe import Qwen3SparseMoeBlock


class Qwen3DecoderLayer:
    """Combine pre-norm Attention and sparse MoE with residual connections."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        input_layernorm_weight: np.ndarray,
        q_proj_weight: np.ndarray,
        k_proj_weight: np.ndarray,
        v_proj_weight: np.ndarray,
        o_proj_weight: np.ndarray,
        q_norm_weight: np.ndarray,
        k_norm_weight: np.ndarray,
        post_attention_layernorm_weight: np.ndarray,
        router_weight: np.ndarray,
        gate_up_proj_weight: np.ndarray,
        down_proj_weight: np.ndarray,
    ) -> None:
        self.hidden_size = config.hidden_size
        self.input_layernorm = RMSNorm(
            input_layernorm_weight, config.rms_norm_eps
        )
        self.self_attention = Qwen3Attention(
            config,
            q_proj_weight,
            k_proj_weight,
            v_proj_weight,
            o_proj_weight,
            q_norm_weight,
            k_norm_weight,
        )
        self.post_attention_layernorm = RMSNorm(
            post_attention_layernorm_weight, config.rms_norm_eps
        )
        self.mlp = Qwen3SparseMoeBlock(
            config,
            router_weight,
            gate_up_proj_weight,
            down_proj_weight,
        )

    def _attention_block(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention(hidden_states, position_ids)
        return residual + hidden_states

    def _moe_block(self, hidden_states: np.ndarray) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        return residual + hidden_states

    def __call__(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._attention_block(hidden_states, position_ids)
        return self._moe_block(hidden_states)

    def _cached_attention_block(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention.cached(
            hidden_states, position_ids, cache, layer_index
        )
        return residual + hidden_states

    def cached(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        """Run one decoder layer while updating its Key/Value cache."""
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._cached_attention_block(
            hidden_states, position_ids, cache, layer_index
        )
        return self._moe_block(hidden_states)


class Qwen3MoeForCausalLM:
    """Run full-prompt Qwen3 MoE inference and return vocabulary logits."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        embed_tokens_weight: np.ndarray,
        layers: list[Qwen3DecoderLayer],
        norm_weight: np.ndarray,
        lm_head_weight: np.ndarray,
    ) -> None:
        if embed_tokens_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("embedding weight does not match config")
        if len(layers) != config.num_hidden_layers:
            raise ValueError("decoder layer count does not match config")
        if norm_weight.shape != (config.hidden_size,):
            raise ValueError("final norm weight does not match config")
        if lm_head_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("LM Head weight does not match config")

        self.embed_tokens = Embedding(embed_tokens_weight)
        self.layers = layers
        self.norm = RMSNorm(norm_weight, config.rms_norm_eps)
        self.lm_head = Linear(lm_head_weight)

    @classmethod
    def from_checkpoint(
        cls,
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
    ) -> "Qwen3MoeForCausalLM":
        embed_tokens_weight = checkpoint.load_tensor("model.embed_tokens.weight")
        layers = [
            cls._load_decoder_layer(config, checkpoint, layer_index)
            for layer_index in range(config.num_hidden_layers)
        ]
        norm_weight = checkpoint.load_tensor("model.norm.weight")
        lm_head_weight = (
            embed_tokens_weight
            if config.tie_word_embeddings
            else checkpoint.load_tensor("lm_head.weight")
        )
        return cls(
            config,
            embed_tokens_weight,
            layers,
            norm_weight,
            lm_head_weight,
        )

    @staticmethod
    def _load_decoder_layer(
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
        layer_index: int,
    ) -> Qwen3DecoderLayer:
        prefix = f"model.layers.{layer_index}"
        load = checkpoint.load_tensor
        return Qwen3DecoderLayer(
            config,
            load(f"{prefix}.input_layernorm.weight"),
            load(f"{prefix}.self_attn.q_proj.weight"),
            load(f"{prefix}.self_attn.k_proj.weight"),
            load(f"{prefix}.self_attn.v_proj.weight"),
            load(f"{prefix}.self_attn.o_proj.weight"),
            load(f"{prefix}.self_attn.q_norm.weight"),
            load(f"{prefix}.self_attn.k_norm.weight"),
            load(f"{prefix}.post_attention_layernorm.weight"),
            load(f"{prefix}.mlp.gate.weight"),
            load(f"{prefix}.mlp.experts.gate_up_proj"),
            load(f"{prefix}.mlp.experts.down_proj"),
        )

    @staticmethod
    def _position_ids(token_ids: np.ndarray) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        positions = np.arange(sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._position_ids(token_ids)
        hidden_states = self.embed_tokens(token_ids)
        for layer in self.layers:
            hidden_states = layer(hidden_states, position_ids)
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

    @staticmethod
    def _cached_position_ids(
        token_ids: np.ndarray, cache: KVCache
    ) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        start = cache.sequence_length
        positions = np.arange(start, start + sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def cached(self, token_ids: np.ndarray, cache: KVCache) -> np.ndarray:
        """Run prefill or decode while appending every layer's Key/Value state."""
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._cached_position_ids(token_ids, cache)
        hidden_states = self.embed_tokens(token_ids)
        for layer_index, layer in enumerate(self.layers):
            hidden_states = layer.cached(
                hidden_states, position_ids, cache, layer_index
            )
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

"""Next-token selection from Causal LM logits."""

from __future__ import annotations

import numpy as np

from qwen3_moe.cache import KVCache

def last_token_logits(logits: np.ndarray) -> np.ndarray:
    """Return the vocabulary logits after the final input token."""
    logits = np.asarray(logits)
    if logits.ndim != 3:
        raise ValueError("logits must have shape [B,S,V]")
    if logits.shape[1] == 0:
        raise ValueError("logits must contain at least one sequence position")
    if logits.shape[2] == 0:
        raise ValueError("logits must contain at least one vocabulary entry")
    return logits[:, -1, :]


def greedy_next_token(logits: np.ndarray) -> np.ndarray:
    """Choose the highest-logit token for each batch item."""
    return np.argmax(last_token_logits(logits), axis=-1)


def next_token_probabilities(
    logits: np.ndarray,
    temperature: float = 1.0,
) -> np.ndarray:
    """Convert final-position logits to probabilities with temperature."""
    if not np.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be a finite positive number")

    scaled_logits = last_token_logits(logits) / temperature
    shifted_logits = scaled_logits - np.max(scaled_logits, axis=-1, keepdims=True)
    unnormalized = np.exp(shifted_logits)
    return unnormalized / np.sum(unnormalized, axis=-1, keepdims=True)


def sample_next_token(
    logits: np.ndarray,
    temperature: float = 1.0,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Sample one token ID per batch item from final-position logits."""
    probabilities = next_token_probabilities(logits, temperature)
    rng = np.random.default_rng() if rng is None else rng
    vocabulary_size = probabilities.shape[-1]
    return np.asarray(
        [
            rng.choice(vocabulary_size, p=batch_probabilities)
            for batch_probabilities in probabilities
        ],
        dtype=np.int64,
    )


def generate_token_ids(
    model: object,
    prompt_token_ids: np.ndarray,
    max_new_tokens: int,
    *,
    eos_token_id: int | None = None,
    temperature: float | None = None,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Generate one continuation with cached prefill and decode."""
    prompt_token_ids = np.asarray(prompt_token_ids)
    if prompt_token_ids.ndim != 2 or prompt_token_ids.shape[0] != 1:
        raise ValueError("generation expects one prompt with shape [1,S]")
    if prompt_token_ids.shape[1] == 0:
        raise ValueError("generation requires at least one prompt token")
    if not np.issubdtype(prompt_token_ids.dtype, np.integer):
        raise ValueError("prompt token IDs must be integers")
    if isinstance(max_new_tokens, bool) or not isinstance(max_new_tokens, int):
        raise TypeError("max_new_tokens must be an integer")
    if max_new_tokens < 0:
        raise ValueError("max_new_tokens cannot be negative")

    generated = prompt_token_ids.astype(np.int64, copy=True)
    if max_new_tokens == 0:
        return generated

    layers = getattr(model, "layers", None)
    if not isinstance(layers, list) or not layers:
        raise ValueError("model must expose a non-empty decoder layer list")
    cache = KVCache(len(layers))
    logits = model.cached(generated, cache)

    for step in range(max_new_tokens):
        next_token = (
            greedy_next_token(logits)
            if temperature is None
            else sample_next_token(logits, temperature, rng)
        )
        generated = np.concatenate((generated, next_token[:, None]), axis=1)
        if eos_token_id is not None and next_token[0] == eos_token_id:
            break
        if step + 1 == max_new_tokens:
            break
        logits = model.cached(next_token[:, None], cache)
    return generated

"""Per-layer Key/Value storage for cached Qwen3 MoE decoding."""

from __future__ import annotations

import numpy as np


class KVCache:
    """Store and append grouped-query Key/Value tensors for every layer."""

    def __init__(self, num_hidden_layers: int) -> None:
        if isinstance(num_hidden_layers, bool) or not isinstance(
            num_hidden_layers, int
        ) or num_hidden_layers <= 0:
            raise ValueError("num_hidden_layers must be a positive integer")
        self._keys: list[np.ndarray | None] = [None] * num_hidden_layers
        self._values: list[np.ndarray | None] = [None] * num_hidden_layers

    def _validate_layer_index(self, layer_index: int) -> None:
        if isinstance(layer_index, bool) or not isinstance(layer_index, int):
            raise TypeError("layer_index must be an integer")
        if not 0 <= layer_index < len(self._keys):
            raise IndexError("layer_index is outside the KV Cache")

    @staticmethod
    def _validate_key_value(key: np.ndarray, value: np.ndarray) -> None:
        if key.ndim != 4 or value.ndim != 4:
            raise ValueError("cached Key and Value must have shape [B,Hkv,S,Dh]")
        if key.shape != value.shape:
            raise ValueError("cached Key and Value shapes must match")
        if key.shape[2] == 0:
            raise ValueError("cached Key and Value must contain at least one token")

    def get(self, layer_index: int) -> tuple[np.ndarray, np.ndarray] | None:
        """Return one layer's cached tensors, or None before its first update."""
        self._validate_layer_index(layer_index)
        key = self._keys[layer_index]
        value = self._values[layer_index]
        if key is None or value is None:
            return None
        return key, value

    def update(
        self,
        layer_index: int,
        key: np.ndarray,
        value: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Append new Key/Value states and return the complete layer cache."""
        self._validate_layer_index(layer_index)
        key = np.asarray(key)
        value = np.asarray(value)
        self._validate_key_value(key, value)

        cached = self.get(layer_index)
        if cached is not None:
            cached_key, cached_value = cached
            if key.shape[:2] + key.shape[3:] != cached_key.shape[:2] + cached_key.shape[3:]:
                raise ValueError("new Key/Value dimensions do not match the layer cache")
            key = np.concatenate((cached_key, key), axis=2)
            value = np.concatenate((cached_value, value), axis=2)

        self._keys[layer_index] = key
        self._values[layer_index] = value
        return key, value

    @property
    def sequence_length(self) -> int:
        """Return the shared cached length after all populated layers agree."""
        lengths = {key.shape[2] for key in self._keys if key is not None}
        if not lengths:
            return 0
        if len(lengths) != 1:
            raise ValueError("KV Cache layers do not have the same sequence length")
        return lengths.pop()

"""Read named tensors from a Safetensors checkpoint."""

from __future__ import annotations

import json
import math
import struct
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np


_DTYPE_WIDTHS = {
    "BF16": 2,
    "F16": 2,
    "F32": 4,
    "I32": 4,
    "I64": 8,
}

_NUMPY_DTYPES = {
    "F16": np.dtype("<f2"),
    "F32": np.dtype("<f4"),
    "I32": np.dtype("<i4"),
    "I64": np.dtype("<i8"),
}


@dataclass(frozen=True, slots=True)
class TensorInfo:
    """Where one tensor lives inside one Safetensors shard."""

    name: str
    dtype: str
    shape: tuple[int, ...]
    shard: str
    data_offsets: tuple[int, int]
    data_start: int


class SafetensorsCheckpoint:
    """A name-to-tensor view over one or more Safetensors files."""

    def __init__(self, directory: Path, tensors: dict[str, TensorInfo]) -> None:
        self.directory = directory
        self._tensors = tensors

    @classmethod
    def from_directory(cls, directory: str | Path) -> "SafetensorsCheckpoint":
        root = Path(directory)
        index_files = sorted(root.glob("*.safetensors.index.json"))
        if index_files:
            tensors = _read_index(root, index_files[0])
        else:
            shards = sorted(root.glob("*.safetensors"))
            if len(shards) != 1:
                raise ValueError("expected one Safetensors file or one index")
            tensors = _read_shard(shards[0])
        return cls(root, tensors)

    def keys(self) -> tuple[str, ...]:
        return tuple(sorted(self._tensors))

    def tensor_info(self, name: str) -> TensorInfo:
        try:
            return self._tensors[name]
        except KeyError as error:
            raise KeyError(f"unknown tensor: {name}") from error

    def load_tensor(self, name: str) -> np.ndarray:
        """Read one tensor payload instead of loading the whole checkpoint."""

        info = self.tensor_info(name)
        start, end = info.data_offsets
        with (self.directory / info.shard).open("rb") as handle:
            handle.seek(info.data_start + start)
            payload = handle.read(end - start)
        if len(payload) != end - start:
            raise ValueError(f"tensor payload is truncated: {name}")

        if info.dtype == "BF16":
            words = np.frombuffer(payload, dtype="<u2").astype(np.uint32)
            array = (words << 16).view(np.float32)
        else:
            array = np.frombuffer(payload, dtype=_NUMPY_DTYPES[info.dtype]).copy()
        return array.reshape(info.shape)


def _read_index(root: Path, path: Path) -> dict[str, TensorInfo]:
    index = json.loads(path.read_text(encoding="utf-8"))
    weight_map = index.get("weight_map")
    if not isinstance(weight_map, dict):
        raise ValueError("Safetensors index must contain weight_map")

    shard_headers = {
        shard_name: _read_shard(root / shard_name)
        for shard_name in sorted(set(weight_map.values()))
    }
    tensors: dict[str, TensorInfo] = {}
    for name, shard_name in weight_map.items():
        try:
            tensors[name] = shard_headers[shard_name][name]
        except KeyError as error:
            raise ValueError(f"index points to a missing tensor: {name}") from error
    return tensors


def _read_shard(path: Path) -> dict[str, TensorInfo]:
    with path.open("rb") as handle:
        prefix = handle.read(8)
        if len(prefix) != 8:
            raise ValueError(f"invalid Safetensors file: {path.name}")
        (header_length,) = struct.unpack("<Q", prefix)
        header = json.loads(handle.read(header_length))

    data_start = 8 + header_length
    data_size = path.stat().st_size - data_start
    tensors: dict[str, TensorInfo] = {}
    for name, metadata in header.items():
        if name != "__metadata__":
            tensors[name] = _tensor_info(
                name, metadata, path.name, data_start, data_size
            )
    return tensors


def _tensor_info(
    name: str,
    metadata: Any,
    shard: str,
    data_start: int,
    data_size: int,
) -> TensorInfo:
    dtype = metadata["dtype"]
    shape = tuple(metadata["shape"])
    start, end = metadata["data_offsets"]
    if dtype not in _DTYPE_WIDTHS:
        raise ValueError(f"unsupported Safetensors dtype: {dtype}")
    if start < 0 or end > data_size:
        raise ValueError(f"tensor offsets are outside {shard}: {name}")
    expected_bytes = math.prod(shape) * _DTYPE_WIDTHS[dtype]
    if end - start != expected_bytes:
        raise ValueError(f"tensor shape does not match its byte range: {name}")
    return TensorInfo(name, dtype, shape, shard, (start, end), data_start)

"""Encode text with the byte-level BPE stored in a Qwen3 tokenizer.json."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Iterable

import regex


class Qwen3Tokenizer:
    """A small, inference-only reader for Qwen3 byte-level BPE assets."""

    def __init__(
        self,
        vocabulary: dict[str, int],
        merges: list[str | list[str]],
        pretoken_pattern: str,
        special_tokens: dict[str, int],
    ) -> None:
        self.vocabulary = vocabulary
        self.tokens = {token_id: token for token, token_id in vocabulary.items()}
        self.special_tokens = special_tokens
        self.special_token_ids = frozenset(special_tokens.values())
        self._merge_ranks = {
            self._parse_merge(pair): rank for rank, pair in enumerate(merges)
        }
        self._pretokenizer = regex.compile(pretoken_pattern)
        self._special_pattern = (
            regex.compile(
                "|".join(
                    regex.escape(token)
                    for token in sorted(special_tokens, key=len, reverse=True)
                )
            )
            if special_tokens
            else None
        )
        self._byte_encoder, self._byte_decoder = _byte_alphabet()
        self._bpe_cache: dict[str, tuple[str, ...]] = {}

    @classmethod
    def from_file(cls, path: str | Path) -> "Qwen3Tokenizer":
        """Read the vocabulary, merge ranks, and special tokens."""

        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        model = raw.get("model")
        if not isinstance(model, dict) or model.get("type") != "BPE":
            raise ValueError("tokenizer.json must contain a BPE model")
        vocabulary = model.get("vocab")
        merges = model.get("merges")
        if not isinstance(vocabulary, dict) or not isinstance(merges, list):
            raise ValueError("tokenizer.json is missing its vocabulary or merges")
        if not all(
            isinstance(token, str) and isinstance(token_id, int)
            for token, token_id in vocabulary.items()
        ):
            raise ValueError("tokenizer vocabulary must map strings to integer IDs")

        special_tokens = {
            item["content"]: item["id"]
            for item in raw.get("added_tokens", [])
            if item.get("special") is True
        }
        full_vocabulary = {**vocabulary, **special_tokens}
        if len(set(full_vocabulary.values())) != len(full_vocabulary):
            raise ValueError("tokenizer IDs must be unique")
        return cls(
            full_vocabulary,
            merges,
            _find_split_pattern(raw.get("pre_tokenizer")),
            special_tokens,
        )

    @staticmethod
    def _parse_merge(pair: str | list[str]) -> tuple[str, str]:
        parts = pair.split(" ", 1) if isinstance(pair, str) else pair
        if len(parts) != 2:
            raise ValueError(f"invalid BPE merge: {pair!r}")
        return parts[0], parts[1]

    @property
    def vocab_size(self) -> int:
        return len(self.vocabulary)

    def token_to_id(self, token: str) -> int:
        try:
            return self.vocabulary[token]
        except KeyError as error:
            raise KeyError(f"unknown token: {token!r}") from error

    def id_to_token(self, token_id: int) -> str:
        try:
            return self.tokens[token_id]
        except KeyError as error:
            raise KeyError(f"unknown token ID: {token_id}") from error

    def encode(self, text: str) -> list[int]:
        """Turn text into the exact token IDs used to index model embeddings."""

        if self._special_pattern is None:
            return self._encode_text(text)

        token_ids: list[int] = []
        start = 0
        for match in self._special_pattern.finditer(text):
            token_ids.extend(self._encode_text(text[start : match.start()]))
            token_ids.append(self.special_tokens[match.group(0)])
            start = match.end()
        token_ids.extend(self._encode_text(text[start:]))
        return token_ids

    def _encode_text(self, text: str) -> list[int]:
        token_ids: list[int] = []
        for match in self._pretokenizer.finditer(text):
            byte_token = "".join(
                self._byte_encoder[byte] for byte in match.group(0).encode("utf-8")
            )
            pieces = self._bpe_cache.get(byte_token)
            if pieces is None:
                pieces = _merge_token(byte_token, self._merge_ranks)
                self._bpe_cache[byte_token] = pieces
            try:
                token_ids.extend(self.vocabulary[piece] for piece in pieces)
            except KeyError as error:
                raise ValueError(f"BPE produced an unknown token: {error.args[0]!r}") from error
        return token_ids

    def decode(
        self,
        token_ids: Iterable[int],
        *,
        skip_special_tokens: bool = False,
        errors: str = "replace",
    ) -> str:
        """Reassemble token IDs into UTF-8 text."""

        output: list[str] = []
        byte_buffer = bytearray()

        def flush_bytes() -> None:
            if byte_buffer:
                output.append(byte_buffer.decode("utf-8", errors=errors))
                byte_buffer.clear()

        for token_id in token_ids:
            token = self.id_to_token(token_id)
            if token_id in self.special_token_ids:
                flush_bytes()
                if not skip_special_tokens:
                    output.append(token)
                continue
            try:
                byte_buffer.extend(self._byte_decoder[character] for character in token)
            except KeyError as error:
                raise ValueError(
                    f"token contains a character outside the byte alphabet: {token!r}"
                ) from error
        flush_bytes()
        return "".join(output)


def _byte_alphabet() -> tuple[dict[int, str], dict[str, int]]:
    """Map all 256 byte values to visible Unicode characters and back."""

    byte_values = list(range(ord("!"), ord("~") + 1))
    byte_values += list(range(ord("¡"), ord("¬") + 1))
    byte_values += list(range(ord("®"), ord("ÿ") + 1))
    code_points = byte_values.copy()
    extra = 0
    for byte in range(256):
        if byte not in byte_values:
            byte_values.append(byte)
            code_points.append(256 + extra)
            extra += 1
    encoder = dict(zip(byte_values, map(chr, code_points), strict=True))
    return encoder, {character: byte for byte, character in encoder.items()}


def _merge_token(
    token: str, merge_ranks: dict[tuple[str, str], int]
) -> tuple[str, ...]:
    """Repeatedly apply the highest-priority merge still present in one token."""

    pieces = tuple(token)
    while len(pieces) > 1:
        adjacent_pairs = zip(pieces, pieces[1:])
        best_pair = min(adjacent_pairs, key=lambda pair: merge_ranks.get(pair, float("inf")))
        if best_pair not in merge_ranks:
            break

        merged: list[str] = []
        index = 0
        while index < len(pieces):
            if index + 1 < len(pieces) and pieces[index : index + 2] == best_pair:
                merged.append("".join(best_pair))
                index += 2
            else:
                merged.append(pieces[index])
                index += 1
        pieces = tuple(merged)
    return pieces


def _find_split_pattern(pretokenizer: object) -> str:
    if not isinstance(pretokenizer, dict):
        raise ValueError("tokenizer.json is missing its pre-tokenizer")
    if pretokenizer.get("type") == "Split":
        pattern = pretokenizer.get("pattern")
        if isinstance(pattern, dict) and isinstance(pattern.get("Regex"), str):
            return pattern["Regex"]
    for child in pretokenizer.get("pretokenizers", []):
        try:
            return _find_split_pattern(child)
        except ValueError:
            pass
    raise ValueError("tokenizer.json does not contain a regex Split pre-tokenizer")

"""Small NumPy layers shared by Qwen3 MoE inference modules."""

from __future__ import annotations

import numpy as np


class Embedding:
    """Look up one hidden vector for every token ID."""

    def __init__(self, weight: np.ndarray) -> None:
        if weight.ndim != 2:
            raise ValueError("embedding weight must have shape [V,D]")
        self.weight = weight

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if not np.issubdtype(token_ids.dtype, np.integer):
            raise ValueError("token IDs must be integers")
        if np.any(token_ids < 0) or np.any(token_ids >= self.weight.shape[0]):
            raise ValueError("token ID is outside the embedding vocabulary")
        return self.weight[token_ids]


class RMSNorm:
    """Scale hidden states by their root-mean-square magnitude."""

    def __init__(self, weight: np.ndarray, epsilon: float) -> None:
        if weight.ndim != 1:
            raise ValueError("RMSNorm weight must have shape [D]")
        if epsilon <= 0:
            raise ValueError("RMSNorm epsilon must be positive")
        self.weight = weight
        self.epsilon = epsilon

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[0]:
            raise ValueError("hidden size does not match RMSNorm weight")
        values = hidden_states.astype(np.float32, copy=False)
        mean_square = np.mean(np.square(values), axis=-1, keepdims=True)
        return values * np.reciprocal(np.sqrt(mean_square + self.epsilon)) * self.weight


class Linear:
    """Apply a learned projection to the last tensor dimension."""

    def __init__(self, weight: np.ndarray, bias: np.ndarray | None = None) -> None:
        if weight.ndim != 2:
            raise ValueError("linear weight must have shape [O,I]")
        if bias is not None and bias.shape != (weight.shape[0],):
            raise ValueError("linear bias must have shape [O]")
        self.weight = weight
        self.bias = bias

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[1]:
            raise ValueError("input size does not match linear weight")
        output = hidden_states @ self.weight.T
        return output if self.bias is None else output + self.bias

"""Rotary position embeddings for Qwen3 attention."""

from __future__ import annotations

import numpy as np


class RotaryEmbedding:
    """Build the cosine and sine values used to rotate attention heads."""

    def __init__(self, head_dim: int, theta: float = 1_000_000.0) -> None:
        if isinstance(head_dim, bool) or not isinstance(head_dim, int) or head_dim <= 0:
            raise ValueError("RoPE head dimension must be a positive integer")
        if head_dim % 2:
            raise ValueError("RoPE head dimension must be even")
        if theta <= 0:
            raise ValueError("RoPE theta must be positive")
        dimensions = np.arange(0, head_dim, 2, dtype=np.float32)
        self.inverse_frequencies = 1.0 / (theta ** (dimensions / head_dim))

    def __call__(self, position_ids: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        position_ids = np.asarray(position_ids)
        if position_ids.ndim != 2:
            raise ValueError("position IDs must have shape [B,S]")
        if not np.issubdtype(position_ids.dtype, np.integer):
            raise ValueError("position IDs must be integers")
        if np.any(position_ids < 0):
            raise ValueError("position IDs must be non-negative")
        angles = position_ids.astype(np.float32)[..., None] * self.inverse_frequencies
        angles = np.concatenate((angles, angles), axis=-1)
        return np.cos(angles), np.sin(angles)


def _rotate_half(hidden_states: np.ndarray) -> np.ndarray:
    first_half, second_half = np.split(hidden_states, 2, axis=-1)
    return np.concatenate((-second_half, first_half), axis=-1)


def apply_rotary_position_embedding(
    query: np.ndarray,
    key: np.ndarray,
    cosine: np.ndarray,
    sine: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    """Rotate Query and Key while allowing different Q and KV head counts."""

    query = np.asarray(query)
    key = np.asarray(key)
    cosine = np.asarray(cosine)
    sine = np.asarray(sine)
    if query.ndim != 4 or key.ndim != 4:
        raise ValueError("Query and Key must have shape [B,H,S,Hd]")
    if query.shape[0] != key.shape[0] or query.shape[2:] != key.shape[2:]:
        raise ValueError("Query and Key must share batch, sequence, and head dimensions")
    expected = (query.shape[0], query.shape[2], query.shape[3])
    if cosine.shape != expected or sine.shape != expected:
        raise ValueError("RoPE cosine and sine must have shape [B,S,Hd]")
    cosine = cosine[:, None, :, :]
    sine = sine[:, None, :, :]
    rotated_query = query * cosine + _rotate_half(query) * sine
    rotated_key = key * cosine + _rotate_half(key) * sine
    return rotated_query, rotated_key

"""Decoder layers and causal language model assembly for Qwen3 MoE."""

from __future__ import annotations

import numpy as np

from qwen3_moe.attention import Qwen3Attention
from qwen3_moe.cache import KVCache
from qwen3_moe.checkpoint import SafetensorsCheckpoint
from qwen3_moe.config import Qwen3MoeConfig
from qwen3_moe.layers import Embedding, Linear
from qwen3_moe.layers import RMSNorm
from qwen3_moe.moe import Qwen3SparseMoeBlock


class Qwen3DecoderLayer:
    """Combine pre-norm Attention and sparse MoE with residual connections."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        input_layernorm_weight: np.ndarray,
        q_proj_weight: np.ndarray,
        k_proj_weight: np.ndarray,
        v_proj_weight: np.ndarray,
        o_proj_weight: np.ndarray,
        q_norm_weight: np.ndarray,
        k_norm_weight: np.ndarray,
        post_attention_layernorm_weight: np.ndarray,
        router_weight: np.ndarray,
        gate_up_proj_weight: np.ndarray,
        down_proj_weight: np.ndarray,
    ) -> None:
        self.hidden_size = config.hidden_size
        self.input_layernorm = RMSNorm(
            input_layernorm_weight, config.rms_norm_eps
        )
        self.self_attention = Qwen3Attention(
            config,
            q_proj_weight,
            k_proj_weight,
            v_proj_weight,
            o_proj_weight,
            q_norm_weight,
            k_norm_weight,
        )
        self.post_attention_layernorm = RMSNorm(
            post_attention_layernorm_weight, config.rms_norm_eps
        )
        self.mlp = Qwen3SparseMoeBlock(
            config,
            router_weight,
            gate_up_proj_weight,
            down_proj_weight,
        )

    def _attention_block(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention(hidden_states, position_ids)
        return residual + hidden_states

    def _moe_block(self, hidden_states: np.ndarray) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        return residual + hidden_states

    def __call__(
        self, hidden_states: np.ndarray, position_ids: np.ndarray
    ) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._attention_block(hidden_states, position_ids)
        return self._moe_block(hidden_states)

    def _cached_attention_block(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        hidden_states = self.self_attention.cached(
            hidden_states, position_ids, cache, layer_index
        )
        return residual + hidden_states

    def cached(
        self,
        hidden_states: np.ndarray,
        position_ids: np.ndarray,
        cache: KVCache,
        layer_index: int,
    ) -> np.ndarray:
        """Run one decoder layer while updating its Key/Value cache."""
        hidden_states = np.asarray(hidden_states)
        if hidden_states.ndim != 3:
            raise ValueError("decoder layer input must have shape [B,S,D]")
        if hidden_states.shape[-1] != self.hidden_size:
            raise ValueError("decoder layer input hidden size does not match config")

        hidden_states = self._cached_attention_block(
            hidden_states, position_ids, cache, layer_index
        )
        return self._moe_block(hidden_states)


class Qwen3MoeForCausalLM:
    """Run full-prompt Qwen3 MoE inference and return vocabulary logits."""

    def __init__(
        self,
        config: Qwen3MoeConfig,
        embed_tokens_weight: np.ndarray,
        layers: list[Qwen3DecoderLayer],
        norm_weight: np.ndarray,
        lm_head_weight: np.ndarray,
    ) -> None:
        if embed_tokens_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("embedding weight does not match config")
        if len(layers) != config.num_hidden_layers:
            raise ValueError("decoder layer count does not match config")
        if norm_weight.shape != (config.hidden_size,):
            raise ValueError("final norm weight does not match config")
        if lm_head_weight.shape != (config.vocab_size, config.hidden_size):
            raise ValueError("LM Head weight does not match config")

        self.embed_tokens = Embedding(embed_tokens_weight)
        self.layers = layers
        self.norm = RMSNorm(norm_weight, config.rms_norm_eps)
        self.lm_head = Linear(lm_head_weight)

    @classmethod
    def from_checkpoint(
        cls,
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
    ) -> "Qwen3MoeForCausalLM":
        embed_tokens_weight = checkpoint.load_tensor("model.embed_tokens.weight")
        layers = [
            cls._load_decoder_layer(config, checkpoint, layer_index)
            for layer_index in range(config.num_hidden_layers)
        ]
        norm_weight = checkpoint.load_tensor("model.norm.weight")
        lm_head_weight = (
            embed_tokens_weight
            if config.tie_word_embeddings
            else checkpoint.load_tensor("lm_head.weight")
        )
        return cls(
            config,
            embed_tokens_weight,
            layers,
            norm_weight,
            lm_head_weight,
        )

    @staticmethod
    def _load_decoder_layer(
        config: Qwen3MoeConfig,
        checkpoint: SafetensorsCheckpoint,
        layer_index: int,
    ) -> Qwen3DecoderLayer:
        prefix = f"model.layers.{layer_index}"
        load = checkpoint.load_tensor
        return Qwen3DecoderLayer(
            config,
            load(f"{prefix}.input_layernorm.weight"),
            load(f"{prefix}.self_attn.q_proj.weight"),
            load(f"{prefix}.self_attn.k_proj.weight"),
            load(f"{prefix}.self_attn.v_proj.weight"),
            load(f"{prefix}.self_attn.o_proj.weight"),
            load(f"{prefix}.self_attn.q_norm.weight"),
            load(f"{prefix}.self_attn.k_norm.weight"),
            load(f"{prefix}.post_attention_layernorm.weight"),
            load(f"{prefix}.mlp.gate.weight"),
            load(f"{prefix}.mlp.experts.gate_up_proj"),
            load(f"{prefix}.mlp.experts.down_proj"),
        )

    @staticmethod
    def _position_ids(token_ids: np.ndarray) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        positions = np.arange(sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._position_ids(token_ids)
        hidden_states = self.embed_tokens(token_ids)
        for layer in self.layers:
            hidden_states = layer(hidden_states, position_ids)
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

    @staticmethod
    def _cached_position_ids(
        token_ids: np.ndarray, cache: KVCache
    ) -> np.ndarray:
        batch_size, sequence_length = token_ids.shape
        start = cache.sequence_length
        positions = np.arange(start, start + sequence_length, dtype=np.int64)
        return np.broadcast_to(positions, (batch_size, sequence_length))

    def cached(self, token_ids: np.ndarray, cache: KVCache) -> np.ndarray:
        """Run prefill or decode while appending every layer's Key/Value state."""
        token_ids = np.asarray(token_ids)
        if token_ids.ndim != 2:
            raise ValueError("Causal LM input must have shape [B,S]")
        if token_ids.shape[1] == 0:
            raise ValueError("Causal LM requires at least one token")

        position_ids = self._cached_position_ids(token_ids, cache)
        hidden_states = self.embed_tokens(token_ids)
        for layer_index, layer in enumerate(self.layers):
            hidden_states = layer.cached(
                hidden_states, position_ids, cache, layer_index
            )
        hidden_states = self.norm(hidden_states)
        return self.lm_head(hidden_states)

"""Next-token selection from Causal LM logits."""

from __future__ import annotations

import numpy as np

from qwen3_moe.cache import KVCache

def last_token_logits(logits: np.ndarray) -> np.ndarray:
    """Return the vocabulary logits after the final input token."""
    logits = np.asarray(logits)
    if logits.ndim != 3:
        raise ValueError("logits must have shape [B,S,V]")
    if logits.shape[1] == 0:
        raise ValueError("logits must contain at least one sequence position")
    if logits.shape[2] == 0:
        raise ValueError("logits must contain at least one vocabulary entry")
    return logits[:, -1, :]


def greedy_next_token(logits: np.ndarray) -> np.ndarray:
    """Choose the highest-logit token for each batch item."""
    return np.argmax(last_token_logits(logits), axis=-1)


def next_token_probabilities(
    logits: np.ndarray,
    temperature: float = 1.0,
) -> np.ndarray:
    """Convert final-position logits to probabilities with temperature."""
    if not np.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be a finite positive number")

    scaled_logits = last_token_logits(logits) / temperature
    shifted_logits = scaled_logits - np.max(scaled_logits, axis=-1, keepdims=True)
    unnormalized = np.exp(shifted_logits)
    return unnormalized / np.sum(unnormalized, axis=-1, keepdims=True)


def sample_next_token(
    logits: np.ndarray,
    temperature: float = 1.0,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Sample one token ID per batch item from final-position logits."""
    probabilities = next_token_probabilities(logits, temperature)
    rng = np.random.default_rng() if rng is None else rng
    vocabulary_size = probabilities.shape[-1]
    return np.asarray(
        [
            rng.choice(vocabulary_size, p=batch_probabilities)
            for batch_probabilities in probabilities
        ],
        dtype=np.int64,
    )


def generate_token_ids(
    model: object,
    prompt_token_ids: np.ndarray,
    max_new_tokens: int,
    *,
    eos_token_id: int | None = None,
    temperature: float | None = None,
    rng: np.random.Generator | None = None,
) -> np.ndarray:
    """Generate one continuation with cached prefill and decode."""
    prompt_token_ids = np.asarray(prompt_token_ids)
    if prompt_token_ids.ndim != 2 or prompt_token_ids.shape[0] != 1:
        raise ValueError("generation expects one prompt with shape [1,S]")
    if prompt_token_ids.shape[1] == 0:
        raise ValueError("generation requires at least one prompt token")
    if not np.issubdtype(prompt_token_ids.dtype, np.integer):
        raise ValueError("prompt token IDs must be integers")
    if isinstance(max_new_tokens, bool) or not isinstance(max_new_tokens, int):
        raise TypeError("max_new_tokens must be an integer")
    if max_new_tokens < 0:
        raise ValueError("max_new_tokens cannot be negative")

    generated = prompt_token_ids.astype(np.int64, copy=True)
    if max_new_tokens == 0:
        return generated

    layers = getattr(model, "layers", None)
    if not isinstance(layers, list) or not layers:
        raise ValueError("model must expose a non-empty decoder layer list")
    cache = KVCache(len(layers))
    logits = model.cached(generated, cache)

    for step in range(max_new_tokens):
        next_token = (
            greedy_next_token(logits)
            if temperature is None
            else sample_next_token(logits, temperature, rng)
        )
        generated = np.concatenate((generated, next_token[:, None]), axis=1)
        if eos_token_id is not None and next_token[0] == eos_token_id:
            break
        if step + 1 == max_new_tokens:
            break
        logits = model.cached(next_token[:, None], cache)
    return generated

"""Per-layer Key/Value storage for cached Qwen3 MoE decoding."""

from __future__ import annotations

import numpy as np


class KVCache:
    """Store and append grouped-query Key/Value tensors for every layer."""

    def __init__(self, num_hidden_layers: int) -> None:
        if isinstance(num_hidden_layers, bool) or not isinstance(
            num_hidden_layers, int
        ) or num_hidden_layers <= 0:
            raise ValueError("num_hidden_layers must be a positive integer")
        self._keys: list[np.ndarray | None] = [None] * num_hidden_layers
        self._values: list[np.ndarray | None] = [None] * num_hidden_layers

    def _validate_layer_index(self, layer_index: int) -> None:
        if isinstance(layer_index, bool) or not isinstance(layer_index, int):
            raise TypeError("layer_index must be an integer")
        if not 0 <= layer_index < len(self._keys):
            raise IndexError("layer_index is outside the KV Cache")

    @staticmethod
    def _validate_key_value(key: np.ndarray, value: np.ndarray) -> None:
        if key.ndim != 4 or value.ndim != 4:
            raise ValueError("cached Key and Value must have shape [B,Hkv,S,Dh]")
        if key.shape != value.shape:
            raise ValueError("cached Key and Value shapes must match")
        if key.shape[2] == 0:
            raise ValueError("cached Key and Value must contain at least one token")

    def get(self, layer_index: int) -> tuple[np.ndarray, np.ndarray] | None:
        """Return one layer's cached tensors, or None before its first update."""
        self._validate_layer_index(layer_index)
        key = self._keys[layer_index]
        value = self._values[layer_index]
        if key is None or value is None:
            return None
        return key, value

    def update(
        self,
        layer_index: int,
        key: np.ndarray,
        value: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Append new Key/Value states and return the complete layer cache."""
        self._validate_layer_index(layer_index)
        key = np.asarray(key)
        value = np.asarray(value)
        self._validate_key_value(key, value)

        cached = self.get(layer_index)
        if cached is not None:
            cached_key, cached_value = cached
            if key.shape[:2] + key.shape[3:] != cached_key.shape[:2] + cached_key.shape[3:]:
                raise ValueError("new Key/Value dimensions do not match the layer cache")
            key = np.concatenate((cached_key, key), axis=2)
            value = np.concatenate((cached_value, value), axis=2)

        self._keys[layer_index] = key
        self._values[layer_index] = value
        return key, value

    @property
    def sequence_length(self) -> int:
        """Return the shared cached length after all populated layers agree."""
        lengths = {key.shape[2] for key in self._keys if key is not None}
        if not lengths:
            return 0
        if len(lengths) != 1:
            raise ValueError("KV Cache layers do not have the same sequence length")
        return lengths.pop()
